SysDataModelXML.SQLScript:
{{
	"type": 3,
	"message": "",
	"condition": "LINKSCRIPTGET@LINK01:SELECT 
CASE WHEN '{5}'='' THEN N'LINKPREVENT:标签数未填写，请检查' 
     WHEN 0#NPTNUM#<0{5} THEN N'LINKCONFIRM:标签数超出0{5}-0#NPTNUM#'
END "
}}

SysDataModelXML.SQLClear:
--LINKREFRESH DECLARE @NPTNUM INT = 0{5}; DECLARE @DOCNUM VARCHAR(30) = '#DOCNUM#'; DECLARE @DOCLIN INT =0#DOCLIN#; DECLARE @TAGNO VARCHAR(30); DECLARE @BATCHID VARCHAR(50)='#LINKID_ACTION#'; DECLARE @CLOT VARCHAR(50)='{6}'; DECLARE @SUBLOT VARCHAR(50)='{7}'; IF @CLOT<>'' UPDATE PBOLD SET LOT=CASE WHEN @CLOT = '' THEN T.LOT ELSE CASE WHEN ITM.TSICOD2 NOT IN('BM') THEN @CLOT ELSE T.LOT END END FROM PBOLD T LEFT JOIN ITM ITM ON T.ITMNO=ITM.ITMNO WHERE DOCNUM=@DOCNUM AND DOCLIN=@DOCLIN
IF @NPTNUM > 0 BEGIN
DECLARE @CTRSEQ INT= 0;
WHILE @CTRSEQ < @NPTNUM BEGIN SET @CTRSEQ = @CTRSEQ + 1; SET @TAGNO = CONCAT('B', REPLACE(STR(NEXT VALUE FOR DOC_CTR, 11), ' ', '0'));
--PRINT @TAGNO INSERT INTO STKLOTLST (DOCTYP ,SITE ,DOCSTA ,ITMNO ,ITMVER ,LOT ,SUBLOT ,TAGTYP ,TAGNO ,PAL ,CTR ,UOM ,UOMCOE ,QTY ,QTYSTU ,STU ,REMARK ,SRCTYP ,SRCDOC ,SRCLIN ,SRCSEQ ,ORITYP ,ORIDOC ,ORILIN ,ORISEQ ,SUBSTA ,SUBTIM ,BATCHID ,CREUSR ,CRETIM) SELECT 'PRC' DOCTYP ,H.SITE ,2 ,T.ITMNO ,T.ITMVER ,CASE WHEN @CLOT = '' THEN T.LOT ELSE CASE WHEN ITM.TSICOD2 NOT IN('BM') THEN @CLOT ELSE T.LOT END END LOT ,@SUBLOT SUBLOT ,'CTR' TAGTYP ,@TAGNO TAGNO ,'' PAL ,@TAGNO CTR ,'PKG' UOM ,T.CTRQTY UOMCOE ,1 QTY ,T.CTRQTY QTYSTU ,T.STU ,T.REMARK ,T.SRCTYP ,T.SRCDOC ,T.SRCLIN ,0 SRCSEQ ,T.DOCTYP ORITYP ,T.DOCNUM ORIDOC ,T.DOCLIN ORILIN ,0 ORISEQ ,3 SUBSTA ,GETDATE() SUBTIM ,@BATCHID BATCHID ,N'#LOGIN_USER#' ,GETDATE() CRETIM FROM [PBOLH] H INNER JOIN [PBOLD] T ON H.DOCNUM = T.DOCNUM LEFT JOIN ITM ITM ON T.ITMNO=ITM.ITMNO WHERE T.DOCNUM=@DOCNUM AND T.DOCLIN=@DOCLIN END END

